import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String API_KEY = System.getenv("INTERNAL_API_KEY");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String category = req.getParameter("category");
        String sortField = req.getParameter("sort");
        String direction = req.getParameter("dir");
        String limit = req.getParameter("limit");

        if (category == null || category.isEmpty()) {
            resp.sendError(400, "category parameter required");
            return;
        }

        // Validate sort direction
        if (direction != null && !direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC")) {
            direction = "ASC";
        }

        // Validate limit is numeric
        int parsedLimit = 50;
        if (limit != null) {
            try {
                parsedLimit = Integer.parseInt(limit);
                if (parsedLimit > 500) parsedLimit = 500;
                if (parsedLimit < 1) parsedLimit = 50;
            } catch (NumberFormatException e) {
                parsedLimit = 50;
            }
        }

        // Allowlist for sort fields to prevent injection via ORDER BY
        String safeSortField = "created_at";
        if (sortField != null) {
            switch (sortField.toLowerCase()) {
                case "name": safeSortField = "name"; break;
                case "price": safeSortField = "price"; break;
                case "created_at": safeSortField = "created_at"; break;
                case "updated_at": safeSortField = "updated_at"; break;
                default: safeSortField = "created_at";
            }
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - category is used in WHERE clause
            String query = "SELECT id, name, price, category, created_at FROM assets WHERE category = '" 
                + category + "' ORDER BY " + safeSortField + " " + direction + " LIMIT " + parsedLimit;

            log.info("Executing query for category: " + category.substring(0, Math.min(category.length(), 20)));

            ResultSet rs = stmt.executeQuery(query);
            JSONArray results = new JSONArray();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("name", rs.getString("name"));
                row.put("price", rs.getDouble("price"));
                row.put("category", rs.getString("category"));
                row.put("created_at", rs.getString("created_at"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            log.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk search endpoint - requires API key
        String authHeader = req.getHeader("X-API-Key");
        if (authHeader == null || !authHeader.equals(API_KEY)) {
            resp.sendError(403, "Forbidden");
            return;
        }
        // Forward to GET handler for simplicity
        doGet(req, resp);
    }
}
